import { createClient, type SupabaseClient } from '@supabase/supabase-js';

let cached: SupabaseClient | null | undefined;

/**
 * Service-role client. Null when [REDACTED] or SUPABASE_SERVICE_ROLE_KEY
 * is missing, which is the local stub path. Never send this key to a browser.
 */
export function getSupabaseAdmin(): SupabaseClient | null {
  if (cached !== undefined) return cached;

  const url = process.env.[REDACTED];
  const key = [REDACTED];
  if (!url || !key) {
    cached = null;
    return null;
  }

  cached = createClient(url, key, {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
    },
  });
  return cached;
}

export function storageMode(): 'memory' | 'supabase' {
  return getSupabaseAdmin() ? 'supabase' : 'memory';
}

import type { Game, GameStatus } from '@grok-hack/api-contract';
import type { SupabaseClient } from '@supabase/supabase-js';

import type { GamePatch, GameRepository, NewGame } from './repository';

type GameRow = {
  id: string;
  parent_prompt: string;
  child_prompt: string;
  child_age: number | null;
  language: string | null;
  status: GameStatus;
  game_url: string | null;
  thumbnail_url: string | null;
  cover_url: string | null;
  assets: unknown;
  error: string | null;
  created_at: string;
  updated_at: string;
};

function assetUrls(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.filter((item): item is string => typeof item === 'string' && item.length > 0);
}

function toIso(value: string): string {
  return new Date(value).toISOString();
}

function rowToGame(row: GameRow): Game {
  return {
    id: row.id,
    parentPrompt: row.parent_prompt,
    childPrompt: row.child_prompt,
    childAge: row.child_age,
    language: row.language,
    status: row.status,
    gameUrl: row.game_url,
    graphics: {
      thumbnailUrl: row.thumbnail_url,
      coverUrl: row.cover_url,
      assetUrls: assetUrls(row.assets),
    },
    error: row.error,
    createdAt: toIso(row.created_at),
    updatedAt: toIso(row.updated_at),
  };
}

export class SupabaseGameRepository implements GameRepository {
  constructor(private readonly client: SupabaseClient) {}

  async insert(input: NewGame): Promise<Game> {
    const { data, error } = await this.client
      .from('games')
      .insert({
        parent_prompt: input.parentPrompt,
        child_prompt: input.childPrompt,
        child_age: input.childAge,
        language: input.language,
        status: 'queued',
        assets: [],
      })
      .select('*')
      .single();

    if (error) {
      throw new Error(`Supabase insert failed: ${error.message}`);
    }
    return rowToGame(data as GameRow);
  }

  async update(id: string, patch: GamePatch): Promise<Game> {
    const row: Record<string, unknown> = {};
    if (patch.status !== undefined) row.status = patch.status;
    if (patch.gameUrl !== undefined) row.game_url = patch.gameUrl;
    if (patch.thumbnailUrl !== undefined) row.thumbnail_url = patch.thumbnailUrl;
    if (patch.coverUrl !== undefined) row.cover_url = patch.coverUrl;
    if (patch.assetUrls !== undefined) row.assets = patch.assetUrls;
    if (patch.error !== undefined) row.error = patch.error;

    const { data, error } = await this.client
      .from('games')
      .update(row)
      .eq('id', id)
      .select('*')
      .single();

    if (error) {
      throw new Error(`Supabase update failed: ${error.message}`);
    }
    return rowToGame(data as GameRow);
  }

  async findById(id: string): Promise<Game | null> {
    const { data, error } = await this.client.from('games').select('*').eq('id', id).maybeSingle();

    if (error) {
      throw new Error(`Supabase read failed: ${error.message}`);
    }
    return data ? rowToGame(data as GameRow) : null;
  }
}

export type GeneratedImage = {
  path: string;
  contentType: string;
  /** TODO: real image bytes. Empty while generation is stubbed. */
  body: Uint8Array;
};

export type GeneratedGraphics = {
  thumbnail: GeneratedImage;
  cover: GeneratedImage;
  assets: GeneratedImage[];
};

/**
 * TODO: Generate a thumbnail, a cover, and any in-game art for the child's
 * concept. Keep the images appropriate for `childAge`. Do not call an image
 * API from this stub.
 *
 * Candidate sources, once implemented: an image model via the Vercel AI
 * Gateway, or a small set of authored templates selected by the model.
 * Upload the bytes in `storeGameAssets`.
 */
export async function generateGraphics(): Promise<GeneratedGraphics> {
  const empty = new Uint8Array();
  return {
    thumbnail: { path: 'thumbnail.svg', contentType: 'image/svg+xml', body: empty },
    cover: { path: 'cover.svg', contentType: 'image/svg+xml', body: empty },
    assets: [{ path: 'assets/placeholder.svg', contentType: 'image/svg+xml', body: empty }],
  };
}

import type { CreateGameRequest, Game } from '@grok-hack/api-contract';

import { deployGame } from '@/lib/services/deploy-game';
import { generateGameCode } from '@/lib/services/generate-game-code';
import { generateGraphics } from '@/lib/services/generate-graphics';
import { storeGameAssets } from '@/lib/services/store-assets';

import type { GameRepository } from './repository';
import { getGameRepository } from './store';

async function runPipeline(repository: GameRepository, game: Game): Promise<Game> {
  try {
    await repository.update(game.id, { status: 'generating' });

    const files = await generateGameCode({
      parentPrompt: game.parentPrompt,
      childPrompt: game.childPrompt,
      childAge: game.childAge,
      language: game.language,
    });
    const graphics = await generateGraphics();
    const stored = await storeGameAssets(game.id, files, graphics);
    const deployed = await deployGame(game.id, stored);

    return await repository.update(game.id, {
      status: 'ready',
      gameUrl: deployed.gameUrl,
      thumbnailUrl: stored.thumbnailUrl,
      coverUrl: stored.coverUrl,
      assetUrls: stored.assetUrls,
      error: null,
    });
  } catch (error) {
    console.error('Game pipeline failed', { gameId: game.id, error });
    return repository.update(game.id, {
      status: 'failed',
      error: 'Game generation failed.',
    });
  }
}

/**
 * Creates the game row, then runs the stub pipeline to `ready`.
 *
 * TODO(async): return the queued row from `insert` and run `runPipeline`
 * in a Vercel Workflow. The route should then respond 202 and the client
 * should poll `GET /api/games/:id` until `ready` or `failed`.
 */
export async function createGame(input: CreateGameRequest): Promise<Game> {
  const repository = getGameRepository();
  const game = await repository.insert({
    parentPrompt: input.parentPrompt,
    childPrompt: input.childPrompt,
    childAge: input.childAge ?? null,
    language: input.language ?? null,
  });
  return runPipeline(repository, game);
}

export type GameCodeRequest = {
  parentPrompt: string;
  childPrompt: string;
  childAge: number | null;
  language: string | null;
};

