import { createClient, type SupabaseClient } from '@supabase/supabase-js';

let cached: SupabaseClient | null = null;
let cachedUrl: string | null = null;
let cachedKey: string | null = null;

/**
 * Service-role client. Null when [REDACTED] or SUPABASE_SERVICE_ROLE_KEY
 * is missing, which is the local stub path. Never send this key to a browser.
 */
export function getSupabaseAdmin(): SupabaseClient | null {
  const url = process.env.[REDACTED]?.trim();
  const key = [REDACTED];
  if (!url || !key) return null;

  if (cached && cachedUrl === url && cachedKey === key) return cached;

  cachedUrl = url;
  cachedKey = key;
  cached = createClient(url, key, {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
    },
  });
  return cached;
}

export function storageMode(): 'memory' | 'supabase' {
  return getSupabaseAdmin() ? 'supabase' : 'memory';
}

