const page = await browser.newPage();
await page.goto('http://localhost:3001/', { waitUntil: 'networkidle0' });
const heading = await page.$eval('main', (el) => el.innerText.slice(0, 400));
console.log('PAGE\n', heading);
const healthHref = await page.$eval('a[href="/api/health"]', (el) => el.getAttribute('href'));
console.log('health link', healthHref);
await page.type('#parentPrompt', 'Addition up to 20');
await page.type('#childPrompt', 'A quiz-show game');
await page.type('#childAge', '10');
await page.type('#language', 'en');
await Promise.all([
  page.waitForResponse((response) => response.url().endsWith('/api/games') && response.request().method() === 'POST'),
  page.click('button[type="submit"]'),
]);
await page.waitForSelector('pre');
const body = JSON.parse(await page.$eval('pre', (el) => el.textContent));
const gameUrlText = await page.$eval('main', (el) => el.innerText);
console.log('status line includes', gameUrlText.includes('Response 201'));
console.log('gameUrl', body.gameUrl);
console.log('thumbnail', body.graphics.thumbnailUrl);
console.log('status', body.status);
if (body.status !== 'ready') throw new Error('expected ready');
if (!String(body.gameUrl).includes('games.example.invalid')) throw new Error('expected placeholder url');
if (!gameUrlText.includes(body.gameUrl)) throw new Error('gameUrl not shown');
if (!gameUrlText.includes('thumbnail')) throw new Error('thumbnail label missing');
const health = await page.goto('http://localhost:3001/api/health');
console.log('health via click-equivalent navigation', await health.text());
await browser.close();
console.log('browser flow ok');
